import { SendAurora } from "@/components/control-ui/extensions/send-aurora";
import type { ControlUiSkin } from "@/components/control-ui/skin";

export const skin: ControlUiSkin = {
  id: "cuicui",
  sidebarLayout: "sidebar",
  sidebarWidth: "20rem",
  adornments: {
    button: {
      layer: (ctx) =>
        ctx.variant === "solid" && ctx.tone !== "danger" ? (
          <span
            aria-hidden
            className="cuicui-animated-gradient pointer-events-none absolute inset-0 rounded-[inherit] opacity-40 mix-blend-overlay"
          />
        ) : null,
    },
    "chat-composer": {
      "send-layer": (ctx) => (
        <SendAurora
          sendCount={ctx.sendCount}
          colors={["var(--cuicui-pink)", "var(--cuicui-orange)", "var(--cuicui-yellow)", "var(--cuicui-sky)", "var(--cuicui-blue)"]}
        />
      ),
    },
  },
};

[data-skin="cuicui"] {
  --cuicui-sky: oklch(0.7676 0.1305 225.406);
  --cuicui-violet: oklch(0.6131 0.2067 283.833);
  --cuicui-rose: oklch(0.6851 0.1761 14.132);
  --cuicui-orange: oklch(0.7259 0.1609 48.691);
  --cuicui-yellow: oklch(0.8659 0.1539 86.484);
  --cuicui-pink: oklch(0.651 0.2092 346.41);
  --cuicui-blue: oklch(0.6871 0.1707 250.704);
  --cuicui-mint: oklch(0.8983 0.0973 174.414);
  --cuicui-gradient: linear-gradient(135deg, var(--cuicui-sky), var(--cuicui-violet), var(--cuicui-rose), var(--cuicui-orange));
  --cuicui-gradient-text: linear-gradient(to right, var(--cuicui-sky), var(--cuicui-violet), var(--cuicui-rose), var(--cuicui-orange));
  --cuicui-gradient-top: linear-gradient(-45deg, var(--cuicui-yellow), var(--cuicui-pink), var(--cuicui-blue), var(--cuicui-mint));
  --cuicui-gradient-soft: linear-gradient(
    135deg,
    oklch(from var(--cuicui-sky) l c h / 0.16),
    oklch(from var(--cuicui-violet) l c h / 0.18),
    oklch(from var(--cuicui-orange) l c h / 0.16)
  );
  --cuicui-noise: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' version='1.1' xmlnsXlink='http://www.w3.org/1999/xlink' viewBox='0 0 700 700' width='700' height='700' opacity='1'%3e%3ctitle%3enoise%3c/title%3e%3cdefs%3e%3cfilter id='nnnoise-filter' x='-20%25' y='-20%25' width='140%25' height='140%25' filterUnits='objectBoundingBox' primitiveUnits='userSpaceOnUse' color-interpolation-filters='linearRGB'%3e%3cfeTurbulence type='fractalNoise' baseFrequency='0.2' numOctaves='4' seed='15' stitchTiles='stitch' x='0%25' y='0%25' width='100%25' height='100%25' result='turbulence'/%3e%3cfeSpecularLighting surfaceScale='5' specularConstant='0.8' specularExponent='20' lighting-color='white' x='0%25' y='0%25' width='100%25' height='100%25' in='turbulence' result='specularLighting'%3e%3cfeDistantLight azimuth='3' elevation='96'/%3e%3c/feSpecularLighting%3e%3cfeColorMatrix type='saturate' values='0' x='0%25' y='0%25' width='100%25' height='100%25' in='specularLighting' result='colormatrix'/%3e%3c/filter%3e%3c/defs%3e%3crect width='700' height='700' fill='black'/%3e%3crect width='700' height='700' fill='white' filter='url(%23nnnoise-filter)'/%3e%3c/svg%3e");
  --cuicui-page-from: oklch(1 0 0);
  --cuicui-page-to: oklch(0.985 0 0);
  --cuicui-page-bg: linear-gradient(to top, var(--cuicui-page-from), var(--cuicui-page-to));
  --cuicui-main-container: oklch(0.985 0 0);
  --cuicui-container-border: oklch(0.708 0 0 / 0.2);
  --cuicui-surface-bg: oklch(1 0 0 / 0.84);
  --cuicui-control-bg: oklch(0.922 0 0 / 0.42);
  --cuicui-control-hover: oklch(0.922 0 0 / 0.28);
  --cuicui-field-bg: oklch(1 0 0 / 0.9);
  --cuicui-border: oklch(from var(--foreground) l c h / 0.16);
  --cuicui-control-shadow: 0 1px 2px oklch(from var(--shadow-color) l c h / 0.06);
  --cuicui-solid-shadow: inset 0 1px 0 oklch(1 0 0 / 0.28), 0 8px 24px oklch(from var(--primary) l c h / 0.24);
}

:where(.dark) [data-skin="cuicui"],
.dark[data-skin="cuicui"] {
  --cuicui-page-from: oklch(0.145 0 0);
  --cuicui-page-to: oklch(0.269 0 0);
  --cuicui-main-container: oklch(0.173 0 0);
  --cuicui-surface-bg: oklch(0.205 0 0 / 0.82);
  --cuicui-control-bg: oklch(0.708 0 0 / 0.14);
  --cuicui-control-hover: oklch(0.708 0 0 / 0.2);
  --cuicui-field-bg: oklch(0.173 0 0 / 0.76);
  --cuicui-border: oklch(1 0 0 / 0.13);
  --cuicui-control-shadow: 0 1px 2px oklch(0 0 0 / 0.18);
}

@layer base {
  :root[data-skin="cuicui"] body {
    min-height: 100dvh;
    background-color: var(--cuicui-page-from);
    background-image: var(--cuicui-page-bg);
  }

  :root[data-skin="cuicui"] body::after {
    content: "";
    position: fixed;
    inset: 0;
    z-index: 9999;
    pointer-events: none;
    user-select: none;
    background-image: var(--cuicui-noise);
    background-size: 400px;
    opacity: 0.05;
    filter: invert(1);
  }

  :root.dark[data-skin="cuicui"] body::after {
    filter: none;
  }
}

@layer components {
  [data-skin="cuicui"] :where([data-control-ui="button"][data-control-family="button"][data-slot="root"], [data-control-ui="toggle"][data-control-family="button"][data-slot="root"]) {
    --button-bg: var(--cuicui-control-bg);
    --button-foreground: var(--foreground);
    --button-hover-bg: var(--cuicui-control-hover);
    --button-hover-foreground: var(--foreground);
    --button-shadow: var(--cuicui-control-shadow);
    --button-press-scale: 0.96;
    --button-focus-shadow: 0 0 0 2px var(--background), 0 0 0 4px var(--ring);
    border: 1px solid var(--cuicui-border);
  }

  [data-skin="cuicui"] :where([data-control-ui="button"][data-control-family="button"][data-slot="root"][data-variant="solid"], [data-control-ui="toggle"][data-control-family="button"][data-slot="root"][data-variant="solid"]) {
    --button-bg: var(--primary);
    --button-foreground: oklch(1 0 0);
    --button-hover-bg: var(--primary);
    --button-hover-foreground: oklch(1 0 0);
    --button-press-bg: var(--primary);
    --button-shadow: var(--cuicui-solid-shadow);
    background-image: var(--cuicui-gradient);
    border-color: transparent;
  }

  [data-skin="cuicui"]
    :where([data-control-ui="button"][data-control-family="button"][data-slot="root"][data-tone="danger"][data-variant="solid"], [data-control-ui="toggle"][data-control-family="button"][data-slot="root"][data-tone="danger"][data-variant="solid"]) {
    --button-bg: var(--destructive);
    --button-foreground: var(--destructive-foreground);
    --button-hover-bg: var(--destructive);
    --button-hover-foreground: var(--destructive-foreground);
    --button-press-bg: var(--destructive);
    --button-shadow: var(--cuicui-control-shadow);
    background-image: none;
    border-color: transparent;
  }

  @media (hover: hover) {
    [data-skin="cuicui"]
      :where([data-control-ui="button"][data-tone="danger"][data-variant="solid"]:hover, [data-control-ui="toggle"][data-tone="danger"][data-variant="solid"]:hover) {
      filter: brightness(1.05);
    }
  }

  [data-skin="cuicui"]
    :where(
      [data-control-ui="toolbar"][data-slot="root"][data-variant="inverse"]
        [data-control-ui="button"][data-control-family="button"][data-slot="root"]
    ) {
    --button-bg: transparent;
    --button-foreground: oklch(from var(--background) l c h / 0.7);
    --button-hover-bg: oklch(from var(--background) l c h / 0.1);
    --button-hover-foreground: var(--background);
    --button-press-bg: oklch(from var(--background) l c h / 0.12);
    --button-active-bg: var(--background);
    --button-active-foreground: var(--foreground);
    --button-active-hover-bg: var(--background);
    --button-shadow: 0 0 transparent;
    --button-active-shadow: 0 0 transparent;
  }

  [data-skin="cuicui"] :where([data-control-ui="button"][data-slot="content"], [data-control-ui="toggle"][data-slot="content"]) {
    gap: 0.375rem;
  }

  [data-skin="cuicui"] .cuicui-gradient-fill {
    background-color: var(--primary);
    background-image: var(--cuicui-gradient);
  }

  [data-skin="cuicui"] .cuicui-gradient-text {
    background-image: var(--cuicui-gradient-text);
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
  }

  [data-skin="cuicui"] .cuicui-animated-gradient {
    background-image: var(--cuicui-gradient-top);
    background-size: 400% 400%;
    animation: cuicui-gradient-animation 5s ease infinite;
  }

  [data-skin="cuicui"] :where([data-control-ui="tabs"][data-control-family="tabs"][data-slot="root"]) {
    --tabs-trigger-radius: calc(var(--radius-control) * 0.78);
    --tabs-list-radius: var(--radius-control);
    --tabs-list-padding: 0.25rem;
    --tabs-list-background: var(--cuicui-control-bg);
    --tabs-active-foreground: var(--primary-foreground);
  }

  [data-skin="cuicui"] [data-control-ui="tabs"][data-slot="indicator"] {
    background: linear-gradient(
      to right,
      oklch(from var(--cuicui-sky) 0.46 c h),
      oklch(from var(--cuicui-violet) 0.46 c h),
      oklch(from var(--cuicui-rose) 0.46 c h),
      oklch(from var(--cuicui-orange) 0.46 c h)
    );
    box-shadow: 0 0 20px oklch(from var(--primary) l c h / 0.22);
  }

  [data-skin="cuicui"] [data-control-ui="tabs"][data-slot="tab"] {
    letter-spacing: -0.01em;
  }

}

@keyframes cuicui-gradient-animation {
  0% {
    -webkit-background-position: 0% 50%;
    background-position: 0% 50%;
  }

  50% {
    -webkit-background-position: 100% 50%;
    background-position: 100% 50%;
  }

  100% {
    -webkit-background-position: 0% 50%;
    background-position: 0% 50%;
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-skin="cuicui"] .cuicui-animated-gradient {
    animation: none;
  }
}

@layer components {
  [data-skin="cuicui"] :where([data-control-family="popup"][data-popup-part="surface"], [data-control-family="popup"][data-popup-part="list-surface"]) {
    --popup-radius: var(--radius-popover);
    --popup-background: oklch(from var(--popover) l c h / 0.9);
    --popup-foreground: var(--popover-foreground);
    --popup-border-color: var(--cuicui-border);
    --popup-border-width: 1px;
    --popup-shadow: var(--shadow-pop);
    --popup-backdrop-blur: var(--backdrop-blur-popover);
  }

  [data-skin="cuicui"] :where([data-popup-part="list-surface"]) {
    padding: 0.25rem;
  }

  [data-skin="cuicui"] :where([data-popup-part="item"]) {
    padding: 0.25rem 0.625rem;
    font-size: 0.8125rem;
  }

  [data-skin="cuicui"] :where([data-popup-part="label"]) {
    padding: 0.25rem 0.5rem;
    font-size: 0.6875rem;
  }

  [data-skin="cuicui"] :where([data-control-family="popup"][data-popup-part="surface"], [data-control-family="popup"][data-popup-part="list-surface"], [data-control-family="popup"][data-popup-part="bar"]) {
    --popup-item-radius: var(--radius-popup-item);
    --popup-item-highlight-background: var(--cuicui-control-bg);
    --popup-item-disabled-opacity: 0.45;
    --popup-separator-color: var(--cuicui-border);
  }

  [data-skin="cuicui"] :where([data-popup-part="separator"]) {
    margin-inline: 0.25rem;
  }

  [data-skin="cuicui"] :where([data-popup-part="shortcut"]) {
    margin-inline-start: auto;
    font-size: 0.6875rem;
    letter-spacing: 0.025em;
  }

  [data-skin="cuicui"] :where([data-control-ui="navigation-menu"][data-slot="viewport"]) {
    padding: 0.25rem;
  }

  [data-skin="cuicui"]
    :where(
      [data-control-ui="select"][data-control-family="button"][data-slot="trigger"],
      [data-control-ui="dropdown-menu"][data-control-family="button"][data-slot="trigger"],
      [data-control-ui="menubar"][data-control-family="button"][data-slot="trigger"]
    ) {
    --button-radius: var(--radius-control);
    --button-bg: var(--cuicui-control-bg);
    --button-foreground: var(--foreground);
    --button-hover-bg: var(--cuicui-control-hover);
    --button-hover-foreground: var(--foreground);
    --button-shadow: var(--cuicui-control-shadow);
    --button-press-scale: 0.96;
    --button-focus-shadow: 0 0 0 2px var(--background), 0 0 0 4px var(--ring);
    border: 1px solid var(--cuicui-border);
  }
  [data-skin="cuicui"] :where([data-control-ui="dialog"][data-control-family="popup"][data-slot="content"][data-surface="modal"], [data-control-ui="alert-dialog"][data-control-family="popup"][data-slot="content"][data-surface="modal"]) {
    --popup-radius: var(--radius-panel);
    --popup-background: var(--cuicui-surface-bg);
    --popup-border-color: var(--cuicui-border);
    --popup-border-width: 1px;
    --popup-shadow: var(--shadow-soft);
    --popup-backdrop-blur: var(--backdrop-blur-popover);
  }

  [data-skin="cuicui"]
    :where(
      [data-control-ui="dialog"][data-popup-part="surface"],
      [data-control-ui="alert-dialog"][data-popup-part="surface"]
    ) {
    padding: 1.5rem;
  }

  [data-skin="cuicui"] :where([data-control-ui="dialog"][data-slot="title"]) {
    font-size: 0.9375rem;
    font-weight: 600;
    letter-spacing: -0.01em;
  }

  [data-skin="cuicui"] :where([data-control-ui="tooltip"][data-control-family="popup"][data-popup-part="surface"]) {
    --popup-radius: var(--radius-control);
    --popup-background: var(--popover);
    --popup-border-color: var(--cuicui-border);
    --popup-border-width: 1px;
    --popup-shadow: var(--shadow-pop);
    padding: 0.375rem 0.625rem;
    font-size: 0.75rem;
  }

}

@layer components {
  [data-skin="cuicui"] :where([data-control-family="field"][data-control="true"]) {
    --field-radius: var(--radius-control);
    --field-background: var(--cuicui-field-bg);
    --field-foreground: var(--foreground);
    --field-border-color: var(--input);
    --field-border-width: 1px;
    --field-shadow: var(--cuicui-control-shadow);
    --field-focus-border-color: var(--input);
    --field-focus-ring-color: var(--ring);
    --field-focus-ring-width: 2px;
  }
}

@layer components {
  [data-skin="cuicui"] :where([data-control-ui="card"][data-control-family="card"][data-slot="root"]) {
    --card-radius: var(--radius-panel);
    --card-background: var(--cuicui-surface-bg);
    --card-border-color: var(--cuicui-border);
    --card-border-width: 1px;
    --card-shadow: var(--shadow-soft);
    --card-backdrop-filter: blur(var(--backdrop-blur-popover));
  }
}
@layer components {
  [data-skin="cuicui"] :where([data-control-ui="color-picker"][data-slot="content"]) {
    @apply rounded-[var(--radius-popover)] border border-[var(--cuicui-border)] bg-popover/90 shadow-(--shadow-pop) backdrop-blur-[var(--backdrop-blur-popover)] p-3;
  }

  [data-skin="cuicui"] :where([data-control-ui="color-picker"][data-slot="panel"]) {
    @apply rounded-[var(--radius-popover)] border border-[var(--cuicui-border)] bg-popover/90 shadow-(--shadow-pop) backdrop-blur-[var(--backdrop-blur-popover)] p-3;
  }

  [data-skin="cuicui"] :where([data-control-ui="command"][data-control-family="popup"][data-slot="root"]) {
    --popup-radius: var(--radius-popover);
    --popup-background: oklch(from var(--popover) l c h / 0.9);
    --popup-border-color: var(--cuicui-border);
    --popup-border-width: 1px;
    --popup-shadow: var(--shadow-pop);
    --popup-backdrop-blur: var(--backdrop-blur-popover);
    overflow: hidden;
    padding: 0.25rem;
  }

  [data-skin="cuicui"] :where([data-control-ui="command"][data-control-family="popup"][data-popup-part="bar"]) {
    --popup-separator-color: var(--cuicui-border);
    --popup-item-radius: var(--radius-popup-item);
    --popup-item-highlight-background: var(--cuicui-control-bg);
    --popup-item-disabled-opacity: 0.45;
  }

  [data-skin="cuicui"] :where([data-control-ui="toast"][data-control-family="toast"][data-slot="root"]) {
    --toast-radius: var(--radius-panel);
    --toast-background: var(--cuicui-surface-bg);
    --toast-border-color: var(--cuicui-border);
    --toast-border-width: 1px;
  }

  [data-skin="cuicui"] :where([data-control-ui="sidebar"][data-slot="wrapper"]) {
    @apply relative isolate;
  }

  [data-skin="cuicui"] :where([data-control-ui="sidebar"][data-slot="inner"]) {
    @apply p-3 backdrop-blur-none text-sidebar-foreground;
  }

  [data-skin="cuicui"] :where([data-control-ui="sidebar"][data-slot="menu-button"]) {
    @apply border border-transparent px-3 text-sm font-medium;
  }

  [data-skin="cuicui"] :where([data-control-ui="sidebar"][data-control-family="sidebar"][data-slot="root"]) {
    --sidebar-wrapper-background: var(--cuicui-page-from);
    --sidebar-wrapper-background-image: var(--cuicui-page-bg);
    --sidebar-inset-background: var(--cuicui-page-from);
    --sidebar-inset-background-image: var(--cuicui-page-bg);
    --sidebar-inner-background: transparent;
    --sidebar-inner-border-width: 0px;
    --sidebar-inner-radius: 0px;
    --sidebar-inner-shadow: none;
    --sidebar-menu-button-radius: var(--radius);
    --sidebar-menu-button-foreground: oklch(0 0 0 / 0.4);
    --sidebar-menu-button-hover-background: oklch(0 0 0 / 0.05);
    --sidebar-menu-button-hover-foreground: oklch(0 0 0 / 0.7);
    --sidebar-menu-button-active-background: oklch(0 0 0 / 0.05);
    --sidebar-menu-button-active-foreground: oklch(0 0 0 / 0.7);
    --sidebar-group-label-foreground: var(--color-neutral-500);
  }

  [data-skin="cuicui"] :where([data-control-ui="sidebar"][data-slot="group-label"]) {
    @apply px-3 py-1 text-xs font-medium tracking-tight;
  }

  .dark [data-skin="cuicui"] :where([data-control-ui="sidebar"][data-control-family="sidebar"][data-slot="root"]) {
    --sidebar-menu-button-foreground: oklch(1 0 0 / 0.4);
    --sidebar-menu-button-hover-background: oklch(1 0 0 / 0.1);
    --sidebar-menu-button-hover-foreground: oklch(1 0 0 / 0.7);
    --sidebar-menu-button-active-background: oklch(1 0 0 / 0.1);
    --sidebar-menu-button-active-foreground: oklch(1 0 0 / 0.8);
    --sidebar-group-label-foreground: var(--color-neutral-400);
  }

  [data-skin="cuicui"] :where([data-control-ui="sidebar-layout"][data-slot="content"]) {
    @apply rounded-[var(--radius)] border border-[var(--cuicui-container-border)] bg-[var(--cuicui-main-container)] shadow-none backdrop-blur-none;
  }

  [data-skin="cuicui"] :where([data-control-ui="alert"][data-control-family="alert"][data-slot="root"]) {
    --alert-radius: var(--radius-panel);
    --alert-background: var(--cuicui-surface-bg);
    --alert-border-color: var(--cuicui-border);
  }

  [data-skin="cuicui"] :where([data-control-ui="badge"][data-control-family="badge"][data-slot="root"]) {
    --badge-radius: 9999px;
    --badge-background: var(--cuicui-control-bg);
    --badge-foreground: var(--muted-foreground);
    --badge-border-color: var(--cuicui-border);
  }

  [data-skin="cuicui"] :where([data-control-ui="item"][data-control-family="item"][data-slot="root"]) {
    --item-radius: var(--radius-control);
    --item-hover-background: var(--cuicui-control-bg);
    --item-hover-border-color: var(--cuicui-border);
    --item-border-width: 1px;
  }

  [data-skin="cuicui"] :where([data-control-ui="empty"][data-control-family="empty"][data-slot="root"]) {
    --empty-radius: var(--radius-panel);
    --empty-background: var(--cuicui-surface-bg);
    --empty-border-color: var(--cuicui-border);
    --empty-border-width: 1px;
    --empty-border-style: dashed;
    --empty-media-radius: var(--radius-control);
    --empty-media-background: var(--cuicui-gradient-soft);
  }


  [data-skin="cuicui"] :where([data-control-ui="slider"][data-control-family="range"][data-slot="root"]) {
    --range-track-background: var(--cuicui-control-bg);
    --range-indicator-background: var(--primary);
    --range-thumb-radius: var(--radius-control);
    --range-thumb-background: var(--cuicui-control-bg);
    --range-thumb-border-color: var(--cuicui-border);
    --range-thumb-shadow: var(--shadow-sm);
  }

  [data-skin="cuicui"] :where([data-control-ui="switch"][data-control-family="switch"][data-slot="root"]) {
    --switch-background: var(--cuicui-control-bg);
    --switch-hover-background: var(--cuicui-control-hover);
    --switch-checked-background: var(--primary);
    --switch-checked-hover-background: var(--primary);
    --switch-thumb-radius: var(--radius-control);
    --switch-thumb-background: var(--cuicui-control-bg);
  }

  [data-skin="cuicui"] :where([data-control-family="choice"]) {
    --choice-radius: calc(var(--radius-control) * 0.55);
    --choice-border-color: var(--cuicui-border);
    --choice-checked-background: var(--primary);
    --choice-checked-border-color: var(--primary);
  }

  [data-skin="cuicui"] :where([data-control-ui="chat-layout"][data-slot="root"]) {
    @apply rounded-[var(--radius-panel)] border border-[var(--cuicui-border)] bg-[var(--cuicui-surface-bg)] shadow-(--shadow-soft) backdrop-blur-[var(--backdrop-blur-popover)];
  }

  [data-skin="cuicui"] :where([data-control-ui="chat-message"][data-control-family="chat-message"][data-slot="root"]) {
    --chat-message-avatar-radius: 9999px;
    --chat-message-avatar-background: var(--cuicui-control-bg);
