  [data-skin="cuicui"] :where([data-control-ui="chat-composer"][data-control-family="chat-composer"][data-slot="root"]) {
    --chat-composer-shell-background: var(--cuicui-field-bg);
    --chat-composer-shell-border-color: var(--input);
    --chat-composer-shell-radius: var(--radius-field);
    --chat-composer-shell-shadow: var(--cuicui-control-shadow);
    --chat-composer-input-foreground: var(--foreground);
    --chat-composer-mention-radius: 9999px;
    --chat-composer-mention-border-color: var(--cuicui-border);
    --chat-composer-mention-border-width: 1px;
    --chat-composer-mention-background: var(--cuicui-control-bg);
  }

  [data-skin="cuicui"] :where([data-control-ui="chat-composer"][data-slot="shell"]) {
    @apply focus-visible:ring-2 focus-visible:ring-[var(--ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-background;
  }

  [data-skin="cuicui"] :where([data-control-ui="chat-composer"][data-slot="submit"]) {
    @apply rounded-[var(--radius-control)] border border-transparent text-white shadow-(--cuicui-solid-shadow) transition-[background-color,border-color,box-shadow,transform] duration-[var(--duration-fast)] ease-[var(--ease-standard)] active:scale-[0.96] focus-visible:ring-2 focus-visible:ring-[var(--ring)] focus-visible:ring-offset-2 focus-visible:ring-offset-background;
    background-color: var(--primary);
    background-image: var(--cuicui-gradient);
  }


  [data-skin="cuicui"] :where([data-control-ui="markdown-block"][data-slot="root"]) {
    @apply rounded-[var(--radius-panel)] border border-[var(--cuicui-border)] bg-[var(--cuicui-surface-bg)] shadow-(--shadow-soft) backdrop-blur-[var(--backdrop-blur-popover)];
  }

  [data-skin="cuicui"] :where([data-control-ui="markdown-block"][data-slot="header"]) {
    @apply border-b border-[var(--cuicui-border)] bg-[var(--cuicui-control-bg)];
  }

  [data-skin="cuicui"] :where([data-control-ui="markdown-block"][data-slot="title"]) {
    @apply font-semibold tracking-[-0.01em];
  }

  [data-skin="cuicui"] :where([data-control-ui="markdown"][data-slot="root"]) {
    @apply text-foreground;
  }

  [data-skin="cuicui"] :where([data-control-ui="code"][data-slot="root"]) {
    @apply rounded-[var(--radius-panel)] border border-[var(--cuicui-border)] bg-[var(--cuicui-surface-bg)] shadow-(--shadow-soft) backdrop-blur-[var(--backdrop-blur-popover)];
  }

  [data-skin="cuicui"] :where([data-control-ui="code"][data-slot="header"]) {
    @apply border-b border-[var(--cuicui-border)] bg-[var(--cuicui-control-bg)];
  }

  [data-skin="cuicui"] :where([data-control-ui="code"][data-slot="title"]) {
    @apply font-mono text-[12px] text-muted-foreground;
  }

  [data-skin="cuicui"] :where([data-control-ui="code-diff"][data-slot="root"]) {
    @apply rounded-[var(--radius-panel)] border border-[var(--cuicui-border)] bg-[var(--cuicui-surface-bg)] shadow-(--shadow-soft) backdrop-blur-[var(--backdrop-blur-popover)];
  }

  [data-skin="cuicui"] :where([data-control-ui="code-diff"][data-slot="header"]) {
    @apply border-b border-[var(--cuicui-border)] bg-[var(--cuicui-control-bg)];
  }

  [data-skin="cuicui"] :where([data-control-ui="inline-attachment"][data-slot="root"]) {
    @apply rounded-[var(--radius-panel)] border border-[var(--cuicui-border)] bg-[var(--cuicui-surface-bg)];
  }

  [data-skin="cuicui"] :where([data-control-ui="inline-attachment"][data-slot="image"]) {
    @apply rounded-[var(--radius-control)];
  }

  [data-skin="cuicui"] :where([data-control-ui="thread-rail"][data-control-family="thread-rail"][data-slot="root"]) {
    --thread-rail-item-radius: 9999px;
    --thread-rail-item-background: var(--cuicui-control-bg);
    --thread-rail-popover-radius: var(--radius-popover);
    --thread-rail-popover-background: oklch(from var(--popover) l c h / 0.9);
    --thread-rail-popover-border-color: var(--cuicui-border);
    --thread-rail-popover-border-width: 1px;
    --thread-rail-popover-shadow: var(--shadow-pop);
    --thread-rail-popover-backdrop-blur: var(--backdrop-blur-popover);
  }

  [data-skin="cuicui"] :where([data-control-ui="progress"][data-control-family="range"][data-slot="root"], [data-control-ui="meter"][data-control-family="range"][data-slot="root"]) {
    --range-track-background: var(--cuicui-control-bg);
    --range-indicator-background: var(--primary);
  }

}

@layer components {
  [data-skin="cuicui"] :where([data-control-ui="activity"][data-slot="status"][data-kind="tool"]) {
    background-image: var(--cuicui-gradient-text);
    background-clip: text;
    -webkit-background-clip: text;
    color: transparent;
    font-weight: 500;
  }

  [data-skin="cuicui"] :where([data-control-ui="chat-message"][data-control-family="chat-message"][data-slot="root"][data-role="user"]) {
    --chat-message-radius: var(--radius-field);
    --chat-message-corner-radius: var(--radius-field);
    --chat-message-background: var(--primary);
    --chat-message-background-image: var(--cuicui-gradient);
    --chat-message-shadow: var(--shadow-sm);
    --chat-message-foreground: white;
  }

  [data-skin="cuicui"] :where([data-control-ui="chat-message"][data-control-family="chat-message"][data-slot="root"][data-role="assistant"]) {
    --chat-message-radius: var(--radius-field);
    --chat-message-corner-radius: var(--radius-field);
    --chat-message-background: transparent;
  }

  [data-skin="cuicui"] :where([data-control-ui="chat-message"][data-slot="content"][data-streaming]) {
    background-image: var(--cuicui-gradient-text);
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
  }

  [data-skin="cuicui"] :where([data-control-ui="skeleton"][data-control-family="skeleton"][data-slot="root"]) {
    --skeleton-background: transparent;
  }

  [data-skin="cuicui"] :where([data-control-ui="skeleton"][data-slot="root"]) {
    background-image: var(--cuicui-gradient-top);
    background-size: 400% 400%;
    animation: cuicui-gradient-animation 5s ease infinite;
  }
}

/* Neutral surfaces, DM Sans rhythm, violet-led accent. Texture, gradient, and glass live in skin.css. */

[data-skin="cuicui"] {
  --font-sans: "DM Sans", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: "Geist Mono", "SF Mono", ui-monospace, Menlo, Consolas, monospace;

  /* type scale — small chrome bumped one rung (11/13px micro/label); body stays 14px */
  --text-micro: 0.6875rem;
  --text-label: 0.8125rem;

  --primary: oklch(0.574 0.2067 283.833);
  --primary-foreground: oklch(1 0 0);
  --destructive: oklch(0.576 0.1761 14.132);
  --destructive-foreground: oklch(1 0 0);
  --popover-opacity: 0.9;
  --backdrop-blur-popover: 16px;
  --overlay-opacity: 0.36;
  --backdrop-blur-overlay: 8px;
  --scroll-fade-size: 2.25rem;

  --shadow-color: oklch(0.145 0 0);
  --shadow-size: 0.7;
  --shadow-opacity: 0.9;
  --shadow-control-multiplier: 0.8;
  --shadow-panel-multiplier: 1.8;
  --shadow-popover-multiplier: 3.2;
  --shadow-modal-multiplier: 4.2;
  --shadow-ambient-multiplier: 6;

  --radius: 10px;
  --radius-control: var(--radius);
  /* radius divergences — copy-paste cards: panels at base radius, 1.85× field, 2× scene; other rungs keep Refined ratios */
  --radius-field: calc(var(--radius) * 1.85);
  --radius-panel: var(--radius);
  --radius-scene: calc(var(--radius) * 2);

  --popover-padding: 0.375rem;
  --radius-popup-item: calc(var(--radius-control) * 0.72);

  --padding-x: 1rem;
  --padding-y: 0.625rem;

  --control-h: 2rem;
  --control-h-xs: round(var(--control-h) * 0.7, 1px);
  --control-h-sm: round(var(--control-h) * 0.85, 1px);
  --control-h-lg: round(var(--control-h) * 1.12, 1px);

  --ease-standard: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-emphasized: cubic-bezier(0.22, 1, 0.36, 1);
  --duration-fast: 150ms;
  --duration-base: 240ms;
  --duration-slow: 420ms;
}

:root:not(.dark)[data-skin="cuicui"],
:where(:not(.dark)) [data-skin="cuicui"] {
  --background: oklch(0.985 0 0);
  --foreground: oklch(0.269 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.269 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.269 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.54 0 0);
  --secondary: oklch(0.922 0 0);
  --secondary-foreground: oklch(0.269 0 0);
  --accent: oklch(0.8659 0.1539 86.484);
  --accent-foreground: oklch(0.269 0 0);
  --border: oklch(from oklch(0.708 0 0) l c h / calc(0.22 * var(--ring-opacity)));
  --input: oklch(from oklch(0.708 0 0) l c h / 0.28);
  --ring: oklch(from var(--primary) l c h / 0.38);
  --canvas: oklch(0.985 0 0);
}

.dark[data-skin="cuicui"],
:where(.dark) [data-skin="cuicui"] {
  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.205 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.205 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --secondary: oklch(0.269 0 0);
  --secondary-foreground: oklch(0.985 0 0);
  --accent: oklch(0.7259 0.1609 48.691);
  --accent-foreground: oklch(0.145 0 0);
  --border: oklch(from oklch(0.708 0 0) l c h / calc(0.16 * var(--ring-opacity)));
  --input: oklch(from oklch(0.708 0 0) l c h / 0.18);
  --ring: oklch(from var(--primary) l c h / 0.52);
  --canvas: oklch(0.145 0 0);
  --popover-opacity: 0.82;
  --shadow-color: oklch(0 0 0);
  --shadow-opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
  [data-skin="cuicui"] {
    --duration-fast: 0ms;
    --duration-base: 0ms;
    --duration-slow: 0ms;
  }
}
